import type { ToggleButtonProps } from "./toggle-button.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "ToggleButton";

// Generate child element class names for the component, should match available style slots
export const ToggleButtonClasses = {
  root: "exp-textura_toggle-button",
  sm: "exp-textura_toggle-button_sm",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: ToggleButtonProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ToggleButtonProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexWrap: "inherit",
    flexDirection: "row",
    width: "fit-content",
    backgroundColor: theme.buttonToggle.color.background,
    borderRadius: theme.buttonToggle.borderRadius,
    padding: `${theme.toRem(0)}`,
    gap: `${theme.toRem(0)}`,

    "&& > button": {
      height: theme.toRem(32),
      backgroundColor: theme.buttonToggle.text.color.background.enabled,
      color: theme.buttonToggle.text.color.content.enabled,
      borderColor: theme.buttonToggle.text.color.border.enabled,

      "&:hover": {
        backgroundColor: theme.buttonToggle.text.color.background.hover,
        color: theme.buttonToggle.text.color.content.hover,
        borderColor: theme.buttonToggle.text.color.border.hover,
        ...styleSlots?.hover,
      },

      "&:active": {
        backgroundColor: theme.buttonToggle.text.color.background.pressed,
        color: theme.buttonToggle.text.color.content.pressed,
        borderColor: theme.buttonToggle.text.color.border.pressed,
        ...styleSlots?.pressed,
      },

      "&[data-selected], &[data-state='on']": {
        backgroundColor: theme.buttonToggle.text.color.background.selected,
        color: theme.buttonToggle.text.color.content.selected,
        borderColor: theme.buttonToggle.text.color.border.selected,
        cursor: "default",
        ...styleSlots?.selected,
      },

      "&:disabled, &:disabled:hover": {
        cursor: "not-allowed",
        backgroundColor: theme.buttonToggle.text.color.background.disabled,
        borderColor: theme.buttonToggle.text.color.border.disabled,
        color: theme.buttonToggle.text.color.content.disabled,
        ...styleSlots?.disabled,
      },

      ...styleSlots?.button,
    },

    "& > button[data-last-selected='true']": {
      cursor: "default",
    },

    [`&.${ToggleButtonClasses.sm}`]: {
      height: theme.toRem(24),
      "& > button": {
        height: theme.toRem(24),
        ...styleSlots?.buttonSm,
      },
      ...styleSlots?.sm,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledToggleButton = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ToggleButtonProps>((props) => generateStyles(props));
